   204	void UnicodeMap::swap(UnicodeMap &other) noexcept
   205	{
   206	  using std::swap;
   207	  swap(encodingName, other.encodingName);
   208	  swap(unicodeOut, other.unicodeOut);
   209	  switch (kind) {
   210	  case unicodeMapUser:
   211	  case unicodeMapResident:
   212	    switch (other.kind) {
   213	    case unicodeMapUser:
   214	    case unicodeMapResident:
   215	      swap(ranges, other.ranges);
   216	      break;
   217	    case unicodeMapFunc:
   218	    {
   219	      const auto tmp = ranges;
   220	      func = other.func;
   221	      other.ranges = tmp;
   222	      break;
   223	    }
   224	    }
   225	    break;
   226	  case unicodeMapFunc:
   227	    switch (other.kind) {
   228	    case unicodeMapUser:
   229	    case unicodeMapResident:
   230	    {
   231	      const auto tmp = func;
   232	      ranges = other.ranges;
   233	      other.func = tmp;
   234	      break;
   235	    }
   236	    case unicodeMapFunc:
   237	      swap(func, other.func);
   238	      break;
   239	    }
   240	    break;
   241	  }
   242	  swap(kind, other.kind);
   243	  swap(len, other.len);
   244	  swap(eMaps, other.eMaps);
   245	  swap(eMapsLen, other.eMapsLen);
   246	}
